import {LEVELS} from './core/maps.js';
import {CANOPY_LEVEL} from './map-layers.js';
import {SCENERY_PROPS,isScenery,isMachine,sceneryRule,scenerySize,sceneryRotation} from './scenery-catalog.js';
import {isHedge} from './hedge-data.js';
import {tilePreview} from './editor-tool-previews.js';
import {STRUCTURE_PRESETS} from './editor-structure-presets.js';
const GROUPS=[
 ['inspect','↖','Select',['inspect']],['land','▲','Land',['land']],['terrain','▦','Tiles',['texture','floor','water','bridge','break-floor']],
 ['objects','▣','Objects',['prop']],['structures','⌂','Structures',['room','prefab']],
 ['roofs','⌑','Roofs',['roof-tile']],['walls','▥','Walls',['wall','door','break-wall']],
 ['cliffs','◩','Cliffs',['cliff','cliff-climb']],['ramps','◿','Ramps',['ramp','ramp-bank']],
 ['people','♟','People',['guard','npc']],['locations','⚑','Locations',['squad','exit']],
 ['access','⇅','Access',['stairs','ladder','ladder-rusty','roof']],['foliage','♣','Foliage',['foliage-cover']],
 ['erase','⌫','Erase',['erase-prop','remove-guard','erase-edge','erase-tile','erase-stairs','erase-roof','erase-cliff','clear-foliage']],['library','▤','Blocks',[]]
];
export function installWorkbench({rotate,clearSelection,getSelection=()=>null}){
 const $=id=>document.getElementById(id),left=document.querySelector('.tools'),right=document.querySelector('.properties'),panel=$('editing-tools'),library=$('workspace').closest('section'),design=$('design-name').closest('section');
 const settings=document.createElement('dialog');settings.id='editor-settings';settings.innerHTML='<div class="settings-heading"><h1>Editor settings</h1><button id="close-settings" aria-label="Close settings">✕</button></div><div id="settings-content"></div>';document.body.append(settings);const content=$('settings-content');
 // Move established controls intact so their saved state and handlers survive the layout change.
 for(const child of [...left.children])if(child!==panel&&child!==library)content.append(child);
 content.append(design,library);for(const d of [...right.querySelectorAll(':scope > details')])content.append(d);
 for(const node of [...right.children])if(node.tagName==='P'&&!node.id||node.tagName==='H2'&&node.textContent==='Design view')content.append(node);
 const selection=document.createElement('section');selection.id='selection-details';selection.setAttribute('aria-label','Selection');
 selection.append($('selected').previousElementSibling,$('selected'),$('properties'),$('visual-note'));right.append(selection);
 const toolsLabel=$('edit-tool').closest('label');toolsLabel.hidden=true;panel.prepend(toolsLabel);right.prepend(panel);panel.querySelector('h2').remove();
 const head=document.createElement('div');head.className='context-heading';head.innerHTML='<p class="eyebrow">Tool options</p><h1 id="active-tool-name">Select</h1><label>Mode<select id="tool-mode"></select></label><p id="tool-description"></p>';panel.prepend(head);
 const stroke=document.createElement('label');stroke.id='stroke-mode-label';stroke.innerHTML='Paint area<select id="stroke-mode"><option value="single">Single tile</option><option value="rectangle">Drag rectangle</option></select>';head.append(stroke);
 const preset=document.createElement('label');preset.id='structure-preset-label';preset.innerHTML='Preset structure<select id="structure-preset"></select>';for(const [id,p]of Object.entries(STRUCTURE_PRESETS))preset.querySelector('select').add(new Option(p.name,id));head.append(preset);$('structure-preset').onchange=()=>{$('edit-tool').value=$('structure-preset').value==='room'?'room':'prefab';$('edit-tool').dispatchEvent(new Event('change'));};
 const gallery=document.createElement('section');gallery.id='tile-gallery';gallery.innerHTML='<label>Find a style<input id="tile-search" type="search" placeholder="Grass, concrete, diagonal…"></label><div id="tile-swatches"></div>';head.append(gallery);
 left.innerHTML='<div class="remote-top"><button id="settings-button" title="Editor settings">⚙<span>Settings</span></button><button id="quick-save-map" title="Save this design">▣<span>Save</span></button></div><p class="remote-caption">BUILD TOOLS</p><nav id="tool-palette" aria-label="Build tools"></nav><div class="remote-view"><button id="quick-overview">Overview</button><button id="quick-home">Center</button><button id="quick-playtest">▶ Playtest</button></div>';
 for(const [id,icon,label]of GROUPS){const b=document.createElement('button');b.dataset.group=id;b.innerHTML=`<span class="tool-symbol" aria-hidden="true">${icon}</span><span>${label}</span>`;b.title=label;b.onclick=()=>activate(id);$('tool-palette').append(b);}
 $('settings-button').onclick=()=>settings.showModal();$('close-settings').onclick=()=>settings.close();$('quick-save-map').onclick=()=>$('save-map').click();$('quick-overview').onclick=()=>$('overview').click();$('quick-home').onclick=()=>$('home').click();$('quick-playtest').onclick=()=>$('playtest').click();
 const bottom=document.createElement('footer');bottom.id='editor-bottom';bottom.innerHTML='<div class="altitude" aria-label="Editing level"><span>Edit level</span></div><div class="edit-actions"></div><span id="altitude-note"></span>';document.body.append(bottom);for(let i=0;i<LEVELS;i++){const b=document.createElement('button');b.textContent=i+1;b.dataset.level=i;b.title=i===CANOPY_LEVEL?`${i+1} · Fringe / authored high terrain`:`${i+1} · Playable level`;b.onclick=()=>{$('floor').value=i;$('floor').dispatchEvent(new Event('change'));};bottom.querySelector('.altitude').append(b);}for(const id of ['undo','redo','rotate-selected','delete-selected'])bottom.querySelector('.edit-actions').append($(id));$('rotate-selected').textContent='↻ Rotate';$('delete-selected').textContent='⌫ Delete selected';$('rotate-selected').onclick=rotate;
 function floorSync(){for(const b of bottom.querySelectorAll('[data-level]'))b.setAttribute('aria-pressed',b.dataset.level===$('floor').value);$('altitude-note').textContent=+$('floor').value===CANOPY_LEVEL?'Fringe layer · roofs or authored high terrain':'';} $('floor').addEventListener('change',floorSync);floorSync();
 const propOptions=[...$('prop-kind').options].map(o=>({value:o.value,label:o.textContent}));const allOptions=[...$('edit-tool').options].map(o=>({value:o.value,label:o.textContent.replace(/^Prop$/,'Objects')}));let group='inspect',remember={};
 const children=[...panel.children].filter(n=>n!==head&&n!==toolsLabel),owner=(id)=>{const e=$(id);return children.find(n=>n===e||n.contains(e));};
 const rules=new Map();function showFor(ids,tools){for(const id of ids){const n=owner(id);if(n)rules.set(n,[...new Set([...(rules.get(n)||[]),...tools])]);}}
 showFor(['site-options'],['prop','inspect']);showFor(['land-options'],['land']);showFor(['ground-kind'],['texture','land']);showFor(['prop-kind'],['prop','roof-tile']);showFor(['edge-kind'],['wall']);showFor(['room-width','room-height'],['room']);showFor(['rotated'],['prop','room','roof-tile','prefab']);showFor(['ramp-options'],['ramp']);showFor(['bank-options'],['ramp-bank']);showFor(['cliff-options'],['cliff']);showFor(['foliage-brush'],['foliage-cover','clear-foliage']);showFor(['foliage-options'],['foliage-cover']);showFor(['foliage-help'],['clear-foliage']);showFor(['unit-species'],['guard','npc','squad']);showFor(['light-mode','apply-light-mode','apply-fixture-condition','aim-spotlight','add-lookout'],['prop','inspect']);showFor(['ramp-bank-surface','add-ramp-banks'],['ramp','inspect']);showFor(['use-selected'],['inspect']);showFor(['apply-door-lock'],['inspect','wall','door']);
 for(const node of children)if(node.tagName==='P'&&!rules.has(node)){const text=node.textContent;rules.set(node,text.startsWith('Cliff climb')?['cliff-climb']:text.startsWith('Ramp props')?['ramp']:text.startsWith('Lookouts')||text.startsWith('Right-click a spotlight')||text.startsWith('Light reaches')?['prop','inspect']:[]);}
 head.insertBefore($('land-options'),gallery);
 function swatches(){const box=$('tile-swatches');box.replaceChildren();const tool=$('edit-tool').value;if(!['texture','land','floor','water','bridge'].includes(tool))return;const entries=['texture','land'].includes(tool)?[...$('ground-kind').options].map(o=>({id:o.value,name:o.textContent})):[{id:tool,name:tool}];for(const item of entries.filter(o=>o.name.toLowerCase().includes($('tile-search').value.toLowerCase()))){const b=document.createElement('button');b.type='button';b.title=item.name;b.setAttribute('aria-label',item.name);b.setAttribute('aria-pressed',!['texture','land'].includes(tool)||$('ground-kind').value===item.id);const img=new Image();img.src=tilePreview(item.id);img.alt='';const text=document.createElement('span');text.textContent=item.name.replaceAll('-',' ');b.append(img,text);b.onclick=()=>{if(['texture','land'].includes(tool)){$('ground-kind').value=item.id;$('ground-kind').dispatchEvent(new Event('change'));}swatches();};box.append(b);}}
 $('tile-search').oninput=swatches;$('ground-kind').addEventListener('change',swatches);
 function context(){const tool=$('edit-tool').value;const current=GROUPS.find(g=>g[3].includes(tool));if(current)group=current[0];remember[group]=tool;const spec=GROUPS.find(g=>g[0]===group);if(['prop','roof-tile'].includes(tool)){const value=$('prop-kind').value,items=propOptions.filter(o=>tool==='roof-tile'?o.value.startsWith('roof-'):!o.value.startsWith('roof-'));$('prop-kind').replaceChildren();for(const label of ['Objects','Scenery','Factory machines']){const optgroup=document.createElement('optgroup');optgroup.label=label;for(const o of items.filter(o=>(isMachine({kind:o.value})?'Factory machines':isScenery({kind:o.value})?'Scenery':'Objects')===label)){const option=new Option(o.label,o.value);if((SCENERY_PROPS[o.value]?.rise||0)>=LEVELS){option.disabled=true;option.textContent+=' · awaiting playable layer 4';}optgroup.append(option);}if(optgroup.children.length)$('prop-kind').append(optgroup);}if(items.some(o=>o.value===value))$('prop-kind').value=value;}$('active-tool-name').textContent=spec[2];for(const b of $('tool-palette').children)b.setAttribute('aria-pressed',b.dataset.group===group);$('tool-mode').replaceChildren(...allOptions.filter(o=>spec[3].includes(o.value)).map(o=>new Option(o.label,o.value)));$('tool-mode').value=tool;$('tool-mode').closest('label').hidden=spec[3].length<2||group==='structures';
 for(const node of children){const allowed=rules.get(node);if(allowed)node.hidden=!allowed.includes(tool);else node.hidden=false;}toolsLabel.hidden=true;head.hidden=false;
 if(group==='inspect'){if(selection.parentNode!==panel)head.after(selection);}else if(selection.parentNode!==right)right.append(selection);
 const hedge=tool==='prop'&&isHedge({kind:$('prop-kind').value});$('stroke-mode-label').hidden=!hedge&&!['erase-prop','texture','floor','water','bridge','break-floor','cliff','erase-tile','erase-cliff'].includes(tool);gallery.hidden=!['texture','land','floor','water','bridge'].includes(tool);preset.hidden=group!=='structures';$('tool-description').textContent=hedge?'Click or drag to plant joined hedges. Leave a tile empty for a gate. Both styles block walking; short hedges screen low sightlines and tall hedges screen standing characters. Leaves conceal; the wooden stems can stop shots.':tool==='break-wall'?'Click an existing brick, concrete or corrugated wall edge and drag along it. Destroyed sections join into a clear opening with broken ends. Erase boundary removes the damage styling; placing a wall repairs the opening.':tool==='break-floor'?'Choose an upper layer, then click or drag across existing structural floor tiles. The holes join with splintered or chipped rims. Move characters, objects and access links first. Paint floor to repair; Erase terrain clears the broken-edge styling.':group==='structures'?'Stamp a small structure. Choose a preset, rotate its footprint, then click to place.':group==='erase'?'Choose what to erase. Undo restores a completed edit.':group==='locations'?'Place squad starting slots or the travel marker.':group==='access'?'Climbing skill controls cost and reliability. Normal ladders have no critical failure; rusty ladders retain a 1% critical failure. Place a normal ladder over a rusty one to repair it.':group==='roofs'?'Climbing skill controls roof access. Choose a roof pattern and altitude. Parapets block climbing. For ladder access, choose a gap direction, add a floor landing just outside that opening at roof height, then place a ladder on that tile from the level below. Rotate turns the gap clockwise. Layer 5 supports decorative roofs and authored high terrain.':'';
 if(hedge){for(const id of ['light-mode','apply-light-mode','apply-fixture-condition','aim-spotlight','add-lookout','rotated','apply-door-lock']){const node=owner(id);if(node)node.hidden=true;}for(const node of children)if(node.tagName==='P'&&/^(Lookouts|Right-click a spotlight|Light reaches)/.test(node.textContent))node.hidden=true;}
 const placingScenery=tool==='prop'&&isScenery({kind:$('prop-kind').value});$('scenery-orientation-label').hidden=!placingScenery;if(placingScenery)$('rotated').closest('label').hidden=true;
 const siteKind=tool==='prop'?$('prop-kind').value:tool==='inspect'?getSelection()?.data?.kind:'';$('machine-options').hidden=!isMachine({kind:siteKind});if(isMachine({kind:siteKind})){const p=tool==='prop'?{kind:siteKind,rotation:+$('scenery-rotation').value}:getSelection().data,r=sceneryRule(p),size=scenerySize(p);$('machine-dimensions').textContent=`${size.w} × ${size.h} tiles · ${sceneryRotation(p)}° · height ${r.height.toFixed(2)} m`;}$('site-options').hidden=!siteKind?.startsWith('site-');$('helicopter-options').hidden=!siteKind?.startsWith('helicopter-');$('set-helicopter-start').disabled=tool!=='inspect'||siteKind!=='helicopter-crash-smoke';$('furnishing-help').hidden=!(siteKind?.startsWith('chair-')||siteKind?.startsWith('guardhouse-'));
 if(group!=='library'&&library.parentNode===panel)content.append(library);swatches();}
 function activate(id){group=id;if(id==='library'){right.append(selection);head.hidden=false;for(const n of children)n.hidden=true;gallery.hidden=true;preset.hidden=true;stroke.hidden=true;$('tool-mode').closest('label').hidden=true;$('active-tool-name').textContent='Blocks & generation';$('tool-description').textContent='Save and place reusable 24 × 24 building blocks.';panel.append(library);library.hidden=false;$('edit-tool').value='inspect';clearSelection();for(const b of $('tool-palette').children)b.setAttribute('aria-pressed',b.dataset.group===id);return;}const spec=GROUPS.find(g=>g[0]===id);$('edit-tool').value=remember[id]||spec[3][0];$('edit-tool').dispatchEvent(new Event('change'));clearSelection();if(id==='inspect')right.scrollTop=0;}
 $('tool-mode').onchange=()=>{$('edit-tool').value=$('tool-mode').value;$('edit-tool').dispatchEvent(new Event('change'));};$('edit-tool').addEventListener('change',context);
 $('prop-kind').addEventListener('change',context);
 document.addEventListener('keydown',e=>{if(e.target.closest?.('input,textarea,select,[contenteditable=true]')||document.querySelector('dialog[open]')||e.ctrlKey||e.metaKey||e.altKey)return;if(/^[1-9]$/.test(e.key)&&+e.key<=LEVELS){e.preventDefault();bottom.querySelector(`[data-level="${+e.key-1}"]`).click();}});
 context();return {context,floorSync};
}
